import sys
from collections import defaultdict, deque
from heapq import heappop, heappush

def dijkstra(n, graph, start):
    dist = [float('inf')] * n
    dist[start] = 0
    pq = [(0, start)]
    while pq:
        d, u = heappop(pq)
        if d > dist[u]:
            continue
        for v, weight in graph[u]:
            if dist[v] > dist[u] + weight:
                dist[v] = dist[u] + weight
                heappush(pq, (dist[v], v))
    return dist

def count_shortest_paths(n, graph, dist, start):
    count = [0] * n
    count[start] = 1
    queue = deque([start])
    while queue:
        u = queue.popleft()
        for v, weight in graph[u]:
            if dist[v] == dist[u] + weight:
                count[v] += count[u]
                if count[v] == 1:
                    queue.append(v)
    return count

def count_road_usage(n, graph, start, dist, shortest_paths):
    usage = defaultdict(int)
    queue = deque([(n-1, 1)])
    while queue:
        u, k = queue.popleft()
        for v, weight in graph[u]:
            new_k = k * shortest_paths[v] // shortest_paths[u]
            if dist[v] == dist[u] - weight:
                usage[(v, u)] += new_k
                if usage[(u, v)] == 0:
                    queue.append((v, new_k))
    return usage

def main():
    import sys
    input = sys.stdin.read().split()
    index = 0
    n = int(input[index])
    m = int(input[index + 1])
    index += 2
    graph = [[] for _ in range(n)]
    for _ in range(m):
        x = int(input[index]) - 1
        y = int(input[index + 1]) - 1
        l = int(input[index + 2])
        index += 3
        graph[x].append((y, l))
        graph[y].append((x, l))

    result = []
    for s in range(n):
        dist = dijkstra(n, graph, s)
        shortest_paths = count_shortest_paths(n, graph, dist, s)
        usage = count_road_usage(n, graph, s, dist, shortest_paths)
        for t in range(s + 1, n):
            result.append(str(usage.get((s, t), 0) + usage.get((t, s), 0)))

    print(' '.join(result))

if __name__ == "__main__":
    main()
